mapper.select:
SELECT FROM schedule s JOIN doctor doc ON doc.id = s.doctor_id AND doc.status = 1 AND doc.role_type = 'DOCTOR' JOIN department dep ON dep.id = doc.department_id AND dep.status = 1 AND dep.type = 'CLINICAL' WHERE s.schedule_date BETWEEN #{startDate} AND #{endDate} AND s.status = 1 AND s.booked_count < s.total_quota
AND s.doctor_id = #{doctorId}
ORDER BY s.doctor_id ASC, s.schedule_date ASC, s.time_slot ASC, s.id ASC

SELECT FROM appointment a JOIN schedule s ON s.id = a.schedule_id JOIN doctor doc ON doc.id = s.doctor_id JOIN department dep ON dep.id = doc.department_id LEFT JOIN prescription p ON p.id = ( SELECT MAX(p2.id) FROM prescription p2 WHERE p2.appointment_id = a.id AND p2.user_id = a.user_id ) WHERE a.user_id = #{userId}
AND a.status IN ('pending', 'confirmed')
AND a.status IN ('pending_rx_pay', 'pending_pickup') AND p.status = 'paid'
AND a.status = #{status}
ORDER BY a.create_time DESC, a.id DESC

SELECT id
FROM appointment
WHERE id = #{id}
  AND user_id = #{userId}

SELECT p.id, p.appointment_id, p.user_id, p.doctor_id, p.total_amount, p.status,
       p.pay_method, p.pay_time, p.create_time, p.update_time
FROM prescription p
JOIN appointment a ON a.id = p.appointment_id AND a.user_id = p.user_id
WHERE p.id = #{id}
  AND p.user_id = #{userId}
